      : undefined,
    simSeed: process.env["SIM_SEED"]
      ? parseInt(process.env["SIM_SEED"])
      : undefined,
    awsRegion: process.env["AWS_REGION"],
    autoApproveDemo: process.env["AUTO_APPROVE_DEMO"] === "1",
  });
}

