// Shared agent loop: Claude thinks, calls tools, reads results, repeats until done.
// Every thinking block, tool call and tool result is saved to agent_steps so /ops
// can replay exactly how each agent worked. MOCK_LLM=1 swaps Claude for a scripted
// stand-in that drives the same tools, so traces work offline.

import Anthropic from "@anthropic-ai/sdk";
import { AnthropicBedrockMantle } from "@anthropic-ai/bedrock-sdk";
import { randomUUID } from "crypto";
import { eq } from "drizzle-orm";
import { config } from "./config.js";
import { getDb } from "./db.js";
import { agentRuns, agentSteps, llmCalls, ledger } from "./schema.js";
import { withSpan } from "./trace.js";

export type AgentName = "operator" | "content" | "analytics" | "support";
export type Effort = "low" | "medium" | "high";

export interface AgentCtx {
  runId?: string;
  simDay: number;
  agentRunId: string;
}

export interface AgentTool {
  name: string;
  description: string;
  input_schema: Anthropic.Tool.InputSchema;
  run: (input: Record<string, unknown>, ctx: AgentCtx) => Promise<unknown>;
}

// One scripted turn for mock mode: what the agent "thinks", then which tools it calls.
export interface MockTurn {
  thinking: string;
  calls?: Array<{ name: string; input: Record<string, unknown> }>;
  answer?: string;
}
export type MockScript = (history: Array<{ name: string; result: unknown }>) => MockTurn;

export interface AgentSpec {
  agent: AgentName;
  system: string;
  tools: AgentTool[];
  effort: Effort;
  mock: MockScript;
}

export interface AgentRunResult {
  agentRunId: string;
  answer: string;
}

const MAX_TURNS = 10;
// Claude Opus 5.5: $4 / $20 per 1M tokens → cents per token
const IN_CENTS_PER_TOKEN = 400 / 1_000_000;
const OUT_CENTS_PER_TOKEN = 2000 / 1_000_000;

let _client: Anthropic | AnthropicBedrockMantle | null = null;
function client() {
  if (_client) return _client;
  _client = process.env["ANTHROPIC_API_KEY"]
    ? new Anthropic()
    : new AnthropicBedrockMantle({ awsRegion: config.awsRegion });
  return _client;
}

function modelId(): string {
  return process.env["ANTHROPIC_API_KEY"] ? config.model : `anthropic.${config.model}`;
}

class StepWriter {
  private seq = 0;
  constructor(private agentRunId: string) {}

  write(step: {
    kind: "thinking" | "text" | "tool_call" | "tool_result" | "error";
    content: string;
    toolName?: string;
    isError?: boolean;
    childRunId?: string;
  }) {
    getDb()
      .insert(agentSteps)
      .values({
        id: randomUUID(),
        agentRunId: this.agentRunId,
        seq: this.seq++,
        kind: step.kind,
        content: step.content,
        toolName: step.toolName ?? null,
        isError: step.isError ?? false,
        childRunId: step.childRunId ?? null,
        ts: new Date(),
      })
      .run();
  }
}

// Sub-agents started from inside a tool register here so the parent's
// tool_result step can link to the child run.
const lastChildRun = new Map<string, string>();

export function noteChildRun(parentAgentRunId: string, childRunId: string) {
  lastChildRun.set(parentAgentRunId, childRunId);
}

export async function runAgent(
  spec: AgentSpec,
  task: string,
  opts: { runId?: string; simDay: number; parentId?: string }
): Promise<AgentRunResult> {
  const db = getDb();
  const agentRunId = randomUUID();
  db.insert(agentRuns)
    .values({
      id: agentRunId,
      runId: opts.runId ?? null,
      parentId: opts.parentId ?? null,
      agent: spec.agent,
      task,
      simDay: opts.simDay,
      startedAt: new Date(),
    })
    .run();
  if (opts.parentId) noteChildRun(opts.parentId, agentRunId);

  const ctx: AgentCtx = { runId: opts.runId, simDay: opts.simDay, agentRunId };
  const steps = new StepWriter(agentRunId);
  const toolsByName = new Map(spec.tools.map((t) => [t.name, t]));
  let costCents = 0;

  return withSpan(`agent:${spec.agent}`, { agent: spec.agent, agent_run_id: agentRunId, task }, async () => {
    try {
      const answer = config.mockLlm
        ? await mockLoop(spec, ctx, steps, toolsByName)
        : await claudeLoop(spec, task, ctx, steps, toolsByName, (c) => (costCents += c));

      db.update(agentRuns)
        .set({ status: "done", result: answer, costCents, endedAt: new Date() })
        .where(eq(agentRuns.id, agentRunId))
        .run();
      return { agentRunId, answer };
    } catch (err) {
      const msg = err instanceof Error ? err.message : String(err);
      steps.write({ kind: "error", content: msg, isError: true });
      db.update(agentRuns)
        .set({ status: "failed", result: msg, costCents, endedAt: new Date() })
        .where(eq(agentRuns.id, agentRunId))
        .run();
      throw err;
    }
  });
}

async function execTool(
  tool: AgentTool | undefined,
  name: string,
  input: Record<string, unknown>,
  ctx: AgentCtx,
  steps: StepWriter
): Promise<{ text: string; isError: boolean }> {
  steps.write({ kind: "tool_call", toolName: name, content: JSON.stringify(input, null, 2) });
  let text: string;
  let isError = false;
  lastChildRun.delete(ctx.agentRunId);
  try {
    if (!tool) throw new Error(`unknown tool ${name}`);
    const result = await withSpan(`tool:${name}`, { tool: name }, () => tool.run(input, ctx));
    text = typeof result === "string" ? result : JSON.stringify(result, null, 2);
  } catch (err) {
    text = err instanceof Error ? err.message : String(err);
    isError = true;
  }
  steps.write({
    kind: "tool_result",
    toolName: name,
    content: text,
    isError,
    ...(lastChildRun.has(ctx.agentRunId) ? { childRunId: lastChildRun.get(ctx.agentRunId)! } : {}),
  });
  return { text, isError };
}

async function claudeLoop(
  spec: AgentSpec,
  task: string,
  ctx: AgentCtx,
  steps: StepWriter,
  toolsByName: Map<string, AgentTool>,
  addCost: (cents: number) => void
): Promise<string> {
  const tools: Anthropic.Tool[] = spec.tools.map(({ name, description, input_schema }) => ({
    name,
    description,
    input_schema,
  }));
  const messages: Anthropic.MessageParam[] = [{ role: "user", content: task }];

  for (let turn = 0; turn < MAX_TURNS; turn++) {
    const response = await withSpan(`llm:${spec.agent}`, { agent: spec.agent, turn }, () =>
      client().messages.create({
        model: modelId(),
        max_tokens: 16000,
        system: spec.system,
        tools,
        thinking: { type: "adaptive", display: "summarized" },
        output_config: { effort: spec.effort },
        messages,
      })
    );

    const cost =
      response.usage.input_tokens * IN_CENTS_PER_TOKEN +
      response.usage.output_tokens * OUT_CENTS_PER_TOKEN;
    addCost(cost);
    recordLlmCost(spec.agent, ctx, response.usage.input_tokens, response.usage.output_tokens, cost);

    // Append the full content unchanged so thinking blocks stay valid next turn.
    messages.push({ role: "assistant", content: response.content });

    const toolUses: Anthropic.ToolUseBlock[] = [];
    let answer = "";
    for (const block of response.content) {
      if (block.type === "thinking" && block.thinking) {
        steps.write({ kind: "thinking", content: block.thinking });
      } else if (block.type === "text" && block.text.trim()) {
        steps.write({ kind: "text", content: block.text });
        answer += block.text;
      } else if (block.type === "tool_use") {
        toolUses.push(block);
      }
    }

    if (response.stop_reason === "refusal") {
      throw new Error(`model declined: ${response.stop_details?.category ?? "unknown"}`);
    }
    if (response.stop_reason !== "tool_use" || toolUses.length === 0) return answer;

    const results: Anthropic.ToolResultBlockParam[] = [];
    for (const use of toolUses) {
      const input = (use.input ?? {}) as Record<string, unknown>;
      const { text, isError } = await execTool(toolsByName.get(use.name), use.name, input, ctx, steps);
      results.push({ type: "tool_result", tool_use_id: use.id, content: text, is_error: isError });
    }
    messages.push({ role: "user", content: results });
  }
  return "Stopped: hit the turn limit.";
}

async function mockLoop(
  spec: AgentSpec,
  ctx: AgentCtx,
  steps: StepWriter,
  toolsByName: Map<string, AgentTool>
): Promise<string> {
  const history: Array<{ name: string; result: unknown }> = [];
  for (let turn = 0; turn < MAX_TURNS; turn++) {
    const step = spec.mock(history);
    steps.write({ kind: "thinking", content: step.thinking });
    if (!step.calls?.length) {
      const answer = step.answer ?? "Done.";
      steps.write({ kind: "text", content: answer });
      return answer;
    }
    for (const call of step.calls) {
      const { text, isError } = await execTool(toolsByName.get(call.name), call.name, call.input, ctx, steps);
      let result: unknown = text;
      try {
        result = JSON.parse(text);
      } catch {
        // plain-text result
      }
      history.push({ name: call.name, result: isError ? { error: text } : result });
    }
  }
  return "Stopped: hit the turn limit.";
}

function recordLlmCost(agent: string, ctx: AgentCtx, inTok: number, outTok: number, cents: number) {
  const db = getDb();
  const callId = randomUUID();
  db.insert(llmCalls)
    .values({
      id: callId,
      runId: ctx.runId ?? null,
      agent,
      model: config.model,
      inTokens: inTok,
      outTokens: outTok,
      costCents: Math.ceil(cents),
      spanId: ctx.agentRunId,
      simDay: ctx.simDay,
    })
    .run();
  if (cents > 0) {
    db.insert(ledger)
      .values({
        id: randomUUID(),
        simDay: ctx.simDay,
        kind: "inference",
        amountCents: -Math.ceil(cents),
        refType: "llm_call",
        refId: callId,
      })
      .run();
  }
}

// Helper for mock scripts: the most recent result of a given tool.
export function lastResult<T = any>(
  history: Array<{ name: string; result: unknown }>,
  name: string
): T | undefined {
  for (let i = history.length - 1; i >= 0; i--) {
    if (history[i]!.name === name) return history[i]!.result as T;
  }
  return undefined;
}

