// Analytics agent: reads the numbers and explains what is and isn't working.
// Read-only — it never changes the store.

import { runAgent, lastResult, type AgentSpec, type AgentTool } from "../core/agent.js";
import { sqlAll } from "../core/db.js";

const cents = (n: number | null | undefined) => `$${((n ?? 0) / 100).toFixed(2)}`;

const tools: AgentTool[] = [
  {
    name: "get_sales_summary",
    description:
      "Revenue, orders, refunds, AI cost and profit so far, overall and per product. Money is in cents.",
    input_schema: { type: "object", properties: {} },
    run: async () => {
      const [totals] = sqlAll<Record<string, number>>(`
        SELECT
          COALESCE(SUM(CASE WHEN kind='revenue' THEN amount_cents END),0) AS revenue,
          COALESCE(SUM(CASE WHEN kind='refund' THEN amount_cents END),0) AS refunds,
          COALESCE(SUM(CASE WHEN kind='fee' THEN amount_cents END),0) AS fees,
          COALESCE(SUM(CASE WHEN kind='inference' THEN amount_cents END),0) AS ai_cost,
          COALESCE(SUM(amount_cents),0) AS profit
        FROM ledger`);
      const byProduct = sqlAll(`
        SELECT p.slug, p.price_cents, COUNT(o.id) AS orders,
               COALESCE(SUM(o.price_paid_cents),0) AS revenue,
               SUM(CASE WHEN o.status='refunded' THEN 1 ELSE 0 END) AS refunded
        FROM products p LEFT JOIN orders o ON o.product_id = p.id
        GROUP BY p.id ORDER BY revenue DESC`);
      return { totals, byProduct };
    },
  },
  {
    name: "get_traffic_sources",
    description:
      "Where visitors come from and how many buy. Includes simulated traffic per channel and real storefront visits per source.",
    input_schema: { type: "object", properties: {} },
    run: async () => {
      const simulated = sqlAll(`
        SELECT c.name AS channel, SUM(t.sessions) AS sessions,
          (SELECT COUNT(*) FROM orders o WHERE o.channel_id = c.id) AS orders
        FROM traffic t JOIN channels c ON c.id = t.channel_id
        GROUP BY c.id`).map((r: any) => ({
        ...r,
        conversionPct: r.sessions ? +((r.orders / r.sessions) * 100).toFixed(2) : 0,
      }));
      const realVisits = sqlAll(
        `SELECT src, COUNT(*) AS visits FROM visits GROUP BY src ORDER BY visits DESC`
      );
      return { simulated, realVisits };
    },
  },
  {
    name: "get_post_performance",
    description: "Each social/blog post the Content agent drafted, with how many visits its tracked link brought.",
    input_schema: { type: "object", properties: {} },
    run: async () =>
      sqlAll(`
        SELECT po.id, c.name AS channel, p.slug AS product, po.status,
               substr(po.body,1,80) AS preview,
               (SELECT COUNT(*) FROM visits v WHERE v.post_id = po.id) AS visits
        FROM posts po JOIN channels c ON c.id = po.channel_id
        LEFT JOIN products p ON p.id = po.product_id
        ORDER BY visits DESC LIMIT 20`),
  },
  {
    name: "get_ai_spend",
    description: "How much each agent has spent on AI calls (cents) and how many calls it made.",
    input_schema: { type: "object", properties: {} },
    run: async () =>
      sqlAll(`SELECT agent, COUNT(*) AS calls, SUM(cost_cents) AS cost_cents
              FROM llm_calls GROUP BY agent ORDER BY cost_cents DESC`),
  },
];

const mock: AgentSpec["mock"] = (history) => {
  const sales = lastResult(history, "get_sales_summary");
  const traffic = lastResult(history, "get_traffic_sources");
  const posts = lastResult<any[]>(history, "get_post_performance");

  if (!sales) {
    return {
      thinking:
        "The operator wants a read on the business. I'll start with money and traffic together — revenue alone doesn't tell me whether the problem is visitors or conversion.",
      calls: [
        { name: "get_sales_summary", input: {} },
        { name: "get_traffic_sources", input: {} },
      ],
    };
  }
  if (!posts) {
    const best = sales.byProduct?.[0];
    const worst = sales.byProduct?.[sales.byProduct.length - 1];
    return {
      thinking: `Revenue is ${cents(sales.totals.revenue)} and profit after AI cost is ${cents(sales.totals.profit)}. ${best?.slug} leads with ${best?.orders} orders; ${worst?.slug} trails with ${worst?.orders}. Before recommending more promotion I need to know whether posts are actually bringing visitors, and what the agents themselves cost.`,
      calls: [
        { name: "get_post_performance", input: {} },
        { name: "get_ai_spend", input: {} },
      ],
    };
  }
  const best = sales.byProduct?.[0];
  const worst = sales.byProduct?.[sales.byProduct.length - 1];
  const channels: any[] = traffic?.simulated ?? [];
  const topChannel = [...channels].sort((a, b) => b.conversionPct - a.conversionPct)[0];
  const postsWithVisits = posts.filter((p) => p.visits > 0).length;
  return {
    thinking: `${posts.length} posts exist, ${postsWithVisits} have brought visits. ${topChannel ? `${topChannel.channel} converts best at ${topChannel.conversionPct}%.` : "No channel data yet."} Enough to give a recommendation.`,
    answer: [
      `Revenue ${cents(sales.totals.revenue)}, profit after AI cost ${cents(sales.totals.profit)} (AI cost ${cents(-sales.totals.ai_cost)}).`,
      `Best seller: ${best?.slug} (${best?.orders} orders). Weakest: ${worst?.slug} (${worst?.orders} orders).`,
      topChannel ? `Best-converting channel: ${topChannel.channel} at ${topChannel.conversionPct}%.` : "",
      `Posts: ${posts.length} drafted, ${postsWithVisits} brought visits.`,
      `Recommendation: promote ${worst?.slug} on ${topChannel?.channel ?? "x"} and check its listing is accurate before spending more on it.`,
    ]
      .filter(Boolean)
      .join("\n"),
  };
};

export const analyticsAgent: AgentSpec = {
  agent: "analytics",
  effort: "low",
  tools,
  mock,
  system: `You are the Analytics agent for AutoShelf, an online store selling digital products.
Your job: answer the Operator's question with numbers. Use your tools to look things up; never guess.
Money from tools is in cents — report it in dollars. Always say how much data a conclusion rests on; if it is very little, say so.
Finish with a short answer: what the numbers show, then one or two concrete recommendations.`,
};

export function askAnalytics(question: string, opts: { runId?: string; simDay: number; parentId?: string }) {
  return runAgent(analyticsAgent, question, opts);
}

