// Support agent: answers buyers, handles delivery problems and refund requests.
// It can refund small amounts itself; anything over the limit is blocked and escalated.

import { randomUUID } from "crypto";
import { eq } from "drizzle-orm";
import { runAgent, lastResult, type AgentSpec, type AgentTool } from "../core/agent.js";
import { getDb, sqlAll } from "../core/db.js";
import { messages, orders, tickets } from "../core/schema.js";
import { check } from "../services/policy.js";
import { recordRefund } from "../services/ledger.js";

function addMessage(ticketId: string, body: string, role: "agent" | "customer" = "agent") {
  getDb().insert(messages).values({ id: randomUUID(), ticketId, role, body }).run();
}

function setTicket(ticketId: string, status: "resolved" | "escalated") {
  getDb().update(tickets).set({ status }).where(eq(tickets.id, ticketId)).run();
}

const tools: AgentTool[] = [
  {
    name: "list_open_tickets",
    description: "Open customer tickets with the customer's message, the order and the product.",
    input_schema: { type: "object", properties: { limit: { type: "number" } } },
    run: async ({ limit }) =>
      sqlAll(
        `SELECT t.id AS ticketId, t.kind, t.order_id AS orderId, p.title AS product,
                o.price_paid_cents AS paidCents, o.status AS orderStatus,
                (SELECT body FROM messages m WHERE m.ticket_id = t.id AND m.role='customer' LIMIT 1) AS customerMessage
         FROM tickets t LEFT JOIN orders o ON o.id = t.order_id
         LEFT JOIN products p ON p.id = o.product_id
         WHERE t.status = 'open' ORDER BY t.sim_day LIMIT ?`,
        Number(limit ?? 5)
      ),
  },
  {
    name: "reply_to_customer",
    description: "Send a reply to the customer and close the ticket.",
    input_schema: {
      type: "object",
      properties: { ticketId: { type: "string" }, message: { type: "string" } },
      required: ["ticketId", "message"],
    },
    run: async ({ ticketId, message }) => {
      addMessage(String(ticketId), String(message));
      setTicket(String(ticketId), "resolved");
      return { ok: true, ticketId, status: "resolved" };
    },
  },
  {
    name: "refund_order",
    description:
      "Refund some or all of an order. Store rules only allow small refunds automatically; larger ones are blocked and must be escalated.",
    input_schema: {
      type: "object",
      properties: {
        ticketId: { type: "string" },
        amountCents: { type: "number" },
        reason: { type: "string" },
      },
      required: ["ticketId", "amountCents", "reason"],
    },
    run: async ({ ticketId, amountCents, reason }, ctx) => {
      const ticket = getDb().select().from(tickets).where(eq(tickets.id, String(ticketId))).get();
      if (!ticket?.orderId) throw new Error("ticket has no order");
      const verdict = check({
        type: "propose_refund",
        orderId: ticket.orderId,
        amountCents: Number(amountCents),
        simDay: ctx.simDay,
        ...(ctx.runId ? { runId: ctx.runId } : {}),
      });
      if (!verdict.allowed) throw new Error(`BLOCKED by store rules: ${verdict.reason}`);
      recordRefund(ctx.simDay, Number(amountCents), ticket.orderId);
      getDb().update(orders).set({ status: "refunded" }).where(eq(orders.id, ticket.orderId)).run();
      addMessage(String(ticketId), `Refunded $${(Number(amountCents) / 100).toFixed(2)}: ${reason}`);
      setTicket(String(ticketId), "resolved");
      return { ok: true, refundedCents: amountCents };
    },
  },
  {
    name: "escalate_to_human",
    description: "Hand the ticket to the store owner when you can't or shouldn't resolve it yourself.",
    input_schema: {
      type: "object",
      properties: { ticketId: { type: "string" }, reason: { type: "string" } },
      required: ["ticketId", "reason"],
    },
    run: async ({ ticketId, reason }) => {
      addMessage(String(ticketId), `Escalated: ${reason}`);
      setTicket(String(ticketId), "escalated");
      return { ok: true, status: "escalated" };
    },
  },
];

const mock: AgentSpec["mock"] = (history) => {
  const open = lastResult<any[]>(history, "list_open_tickets");
  if (!open) {
    return {
      thinking: "Checking the support queue first so I know what's waiting.",
      calls: [{ name: "list_open_tickets", input: { limit: 3 } }],
    };
  }
  const handled = new Set(
    history.filter((h) => h.name !== "list_open_tickets").map((h: any) => h.result?.ticketId ?? h.ticketId)
  );
  const done = history.filter((h) => h.name !== "list_open_tickets").length;
  const next = open[done];
  if (!next) {
    const blocked = history.filter((h: any) => h.name === "refund_order" && h.result?.error).length;
    return {
      thinking: "Queue handled. Summarising for the operator.",
      answer: open.length
        ? `Handled ${open.length} ticket(s). ${blocked} refund(s) were over the limit and went to a human.`
        : "No open tickets.",
    };
  }
  const last = history[history.length - 1] as any;
  if (last?.name === "refund_order" && last.result?.error && !handled.has("esc")) {
    // previous refund was blocked → escalate that ticket
    const prev = open[done - 1];
    return {
      thinking: `The refund for ticket ${prev.ticketId.slice(0, 8)} was blocked — it's above what I'm allowed to refund. That's correct behaviour; a human should decide. Escalating.`,
      calls: [{ name: "escalate_to_human", input: { ticketId: prev.ticketId, reason: "full refund above auto-approve limit" } }],
    };
  }
  if (next.kind === "refund") {
    return {
      thinking: `Ticket ${next.ticketId.slice(0, 8)}: customer wants a refund for "${next.product}" (paid $${(next.paidCents / 100).toFixed(2)}). They say: "${next.customerMessage}". A full refund is fair; I'll try it and let the store rules decide if it needs approval.`,
      calls: [{ name: "refund_order", input: { ticketId: next.ticketId, amountCents: next.paidCents, reason: "customer not satisfied" } }],
    };
  }
  return {
    thinking: `Ticket ${next.ticketId.slice(0, 8)} is a ${next.kind}: "${next.customerMessage}". This needs an answer, not money. Replying with help.`,
    calls: [
      {
        name: "reply_to_customer",
        input: {
          ticketId: next.ticketId,
          message: `Sorry about that! Your download link for "${next.product}" is in your order email and stays valid for 72 hours. Reply here if anything is still unclear.`,
        },
      },
    ],
  };
};

export const supportAgent: AgentSpec = {
  agent: "support",
  effort: "low",
  tools,
  mock,
  system: `You are the Support agent for AutoShelf, an online store selling digital products.
Work through open tickets: answer questions, fix delivery problems, handle refund requests fairly.
You may attempt refunds; the store rules decide. If a refund is blocked, escalate that ticket to a human — never retry with a smaller amount just to get past the limit.
Be brief and kind with customers. Finish with a one-line summary of what you did.`,
};

export function runSupport(opts: { runId?: string; simDay: number; parentId?: string }) {
  return runAgent(supportAgent, "Handle the open support tickets (up to 3).", opts);
}

