import { runSupport } from "./support.js";

const tools: AgentTool[] = [
  {
    name: "get_store_snapshot",
    description: "Quick overview: products and prices, money so far, open tickets, posts drafted, AI spend.",
    input_schema: { type: "object", properties: {} },
    run: async () => ({
      products: sqlAll(`SELECT slug, title, price_cents, cost_cents_est, status, version FROM products`),
      money: sqlAll(`SELECT kind, SUM(amount_cents) AS cents FROM ledger GROUP BY kind`),
      openTickets: sqlAll<{ n: number }>(`SELECT COUNT(*) AS n FROM tickets WHERE status='open'`)[0]?.n ?? 0,
      postsDrafted: sqlAll<{ n: number }>(`SELECT COUNT(*) AS n FROM posts`)[0]?.n ?? 0,
    }),
  },
  {
    name: "ask_analytics",
    description: "Ask the Analytics agent a question about sales, traffic sources, posts or AI cost. Returns its answer.",
    input_schema: {
      type: "object",
      properties: { question: { type: "string" } },
      required: ["question"],
    },
    run: async ({ question }, ctx) => {
      const r = await askAnalytics(String(question), { ...opts(ctx), parentId: ctx.agentRunId });
      return { agentRunId: r.agentRunId, answer: r.answer };
    },
  },
  {
    name: "assign_content",
    description:
      "Give the Content agent a job for one product: fix/improve its listing and/or draft promo posts. Say which product (slug) and what you want.",
    input_schema: {
      type: "object",
      properties: { slug: { type: "string" }, instructions: { type: "string" } },
      required: ["slug", "instructions"],
    },
    run: async ({ slug, instructions }, ctx) => {
      const r = await assignContent(`Product: ${slug}\n${instructions}`, { ...opts(ctx), parentId: ctx.agentRunId });
      return { agentRunId: r.agentRunId, answer: r.answer };
    },
  },
  {
    name: "run_support",
    description: "Have the Support agent work through open customer tickets.",
    input_schema: { type: "object", properties: {} },
    run: async (_input, ctx) => {
      const r = await runSupport({ ...opts(ctx), parentId: ctx.agentRunId });
      return { agentRunId: r.agentRunId, answer: r.answer };
    },
  },
  {
    name: "set_price",
    description: "Change a product's price (cents). Blocked if the price would leave less than the minimum profit margin.",
    input_schema: {
      type: "object",
      properties: { slug: { type: "string" }, priceCents: { type: "number" }, reason: { type: "string" } },
      required: ["slug", "priceCents", "reason"],
    },
    run: async ({ slug, priceCents }, ctx) => {
      const p = getDb().select().from(products).where(eq(products.slug, String(slug))).get();
      if (!p) throw new Error(`no product ${slug}`);
      const verdict = check({
        type: "set_price",
        productId: p.id,
        newPriceCents: Number(priceCents),
        costCentsEst: p.costCentsEst,
        simDay: ctx.simDay,
        ...(ctx.runId ? { runId: ctx.runId } : {}),
      });
      if (!verdict.allowed) throw new Error(`BLOCKED by store rules: ${verdict.reason}`);
      getDb().update(products).set({ priceCents: Number(priceCents) }).where(eq(products.id, p.id)).run();
      return { ok: true, slug, oldPriceCents: p.priceCents, newPriceCents: priceCents };
    },
  },
];

function opts(ctx: { runId?: string | undefined; simDay: number }) {
  return { simDay: ctx.simDay, ...(ctx.runId ? { runId: ctx.runId } : {}) };
}

const mock: AgentSpec["mock"] = (history) => {
  const snap = lastResult(history, "get_store_snapshot");
  const analysis = lastResult(history, "ask_analytics");
  const support = lastResult(history, "run_support");
  const content = lastResult(history, "assign_content");

  if (!snap) {
