  }
  return {
    thinking: "Three actions done this round. Next check-in will show whether the new post brings visits.",
    answer: [
      `Analytics: ${analysis.answer.split("\n")[0]}`,
      support ? `Support: ${support.answer}` : "",
      `Content: ${content.answer}`,
    ]
      .filter(Boolean)
      .join("\n"),
  };
};

export const operatorAgent: AgentSpec = {
  agent: "operator",
  effort: "medium",
  tools,
  mock,
  system: `You are the Operator of AutoShelf, an online store selling digital products. You run it with three helpers: Analytics, Content and Support.
Goal: more buyers and more profit after AI costs. Each check-in, take at most 3 actions.
- Look before acting: get the snapshot, and ask Analytics before deciding what to promote.
- Handle waiting customers before chasing new ones.
