// /ops — watch the agents work. Lists check-ins and replays each agent's
// thinking, tool calls and tool results, with sub-agent runs nested inline.

import { Hono } from "hono";
import { sqlAll } from "../core/db.js";
import { liveCheckIn } from "../agents/run-live.js";

export const ops = new Hono();

export function esc(s: unknown): string {
  return String(s ?? "")
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;");
}

const AGENT_COLOR: Record<string, string> = {
  operator: "#818cf8",
  analytics: "#2dd4bf",
  content: "#fbbf24",
  support: "#fb7185",
};

interface RunRow {
  id: string;
  parent_id: string | null;
  agent: string;
  task: string;
  status: string;
  result: string | null;
  cost_cents: number;
  sim_day: number;
  started_at: number;
  ended_at: number | null;
}

interface StepRow {
  seq: number;
  kind: string;
  tool_name: string | null;
  content: string;
  is_error: number;
  child_run_id: string | null;
}

function page(title: string, body: string, refresh = false) {
  return `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
${refresh ? '<meta http-equiv="refresh" content="3">' : ""}
<title>${esc(title)} · AutoShelf ops</title>
<style>
:root{--bg:#0b0d12;--panel:#12151d;--line:#232836;--text:#e6e8ee;--muted:#8b93a7}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px/1.55 system-ui,-apple-system,sans-serif}
a{color:inherit}header{display:flex;gap:16px;align-items:center;padding:14px 20px;border-bottom:1px solid var(--line)}
header b{font-size:16px}header .sp{flex:1}main{max-width:980px;margin:0 auto;padding:20px 16px 80px}
.btn{background:#4f46e5;color:#fff;border:0;border-radius:8px;padding:8px 14px;font-weight:600;cursor:pointer}
table{width:100%;border-collapse:collapse}td,th{padding:10px 8px;border-bottom:1px solid var(--line);text-align:left;vertical-align:top}
th{color:var(--muted);font-weight:500;font-size:12px;text-transform:uppercase;letter-spacing:.04em}
.tag{display:inline-block;padding:1px 8px;border-radius:999px;font-size:12px;font-weight:600;color:#0b0d12}
.muted{color:var(--muted)}.run{border-left:3px solid var(--c);background:var(--panel);border-radius:8px;padding:12px 14px;margin:10px 0}
.run>.head{display:flex;gap:10px;align-items:baseline;flex-wrap:wrap;margin-bottom:6px}
.step{margin:8px 0;padding:8px 10px;border-radius:6px;background:#0e1118;border:1px solid var(--line)}
.think{font-style:italic;color:#c4b5fd;background:#151225;border-color:#2b2347}
.call{font-family:ui-monospace,Menlo,monospace;font-size:12.5px}.call b{color:var(--c)}
.err{border-color:#7f1d1d;background:#1c0f12;color:#fca5a5}.answer{border-color:#14532d;background:#0d1a12}
pre{margin:6px 0 0;white-space:pre-wrap;word-break:break-word;font:12px/1.5 ui-monospace,Menlo,monospace;color:#cbd5e1;max-height:320px;overflow:auto}
summary{cursor:pointer;color:var(--muted);font-size:12.5px}.label{font-size:11px;text-transform:uppercase;letter-spacing:.05em;color:var(--muted);margin-bottom:2px}
.legend span{margin-right:10px}
</style></head><body>
<header><b><a href="/ops" style="text-decoration:none">AutoShelf · agent activity</a></b>
<span class="legend muted">${Object.entries(AGENT_COLOR)
    .map(([a, c]) => `<span><span class="tag" style="background:${c}">${a}</span></span>`)
    .join("")}</span><span class="sp"></span><a href="/" class="muted">Store →</a></header>
<main>${body}</main></body></html>`;
}

const money = (c: number) => `$${(c / 100).toFixed(3)}`;
const time = (ms: number) => new Date(ms).toLocaleString();
const dur = (r: RunRow) => (r.ended_at ? `${((r.ended_at - r.started_at) / 1000).toFixed(1)}s` : "running…");

ops.get("/", (c) => {
  const runs = sqlAll<RunRow & { children: number; steps: number }>(`
    SELECT r.*,
      (SELECT COUNT(*) FROM agent_runs k WHERE k.parent_id = r.id) AS children,
      (SELECT COUNT(*) FROM agent_steps s WHERE s.agent_run_id = r.id) AS steps
    FROM agent_runs r WHERE r.parent_id IS NULL
    ORDER BY r.started_at DESC LIMIT 50`);
  const anyRunning = runs.some((r) => r.status === "running");
  const rows = runs
    .map(
      (r) => `<tr>
      <td><span class="tag" style="background:${AGENT_COLOR[r.agent] ?? "#999"}">${esc(r.agent)}</span></td>
      <td><a href="/ops/run/${r.id}">${esc(r.task)}</a><div class="muted">${esc((r.result ?? "").split("\n")[0]).slice(0, 160)}</div></td>
      <td>${r.children} helpers · ${r.steps} steps</td>
      <td>${esc(r.status)}<div class="muted">${dur(r)}</div></td>
      <td class="muted">${time(r.started_at)}</td></tr>`
    )
    .join("");
  return c.html(
    page(
      "Activity",
      `<div style="display:flex;align-items:center;gap:12px;margin-bottom:16px">
        <h2 style="margin:0;flex:1">Check-ins</h2>
        <form method="post" action="/ops/check-in"><button class="btn">Run agents now</button></form></div>
      <table><tr><th>Agent</th><th>Task / outcome</th><th>Work</th><th>Status</th><th>Started</th></tr>
      ${rows || `<tr><td colspan="5" class="muted">No agent runs yet. Click “Run agents now”.</td></tr>`}</table>`,
      anyRunning
    )
  );
});

let checkInRunning = false;
ops.post("/check-in", (c) => {
  if (!checkInRunning) {
    checkInRunning = true;
    liveCheckIn()
      .catch((e) => console.error("[ops] check-in failed", e))
      .finally(() => (checkInRunning = false));
  }
  return c.redirect("/ops");
});

function renderRun(runId: string, depth = 0): string {
  const [r] = sqlAll<RunRow>(`SELECT * FROM agent_runs WHERE id = ?`, runId);
  if (!r || depth > 5) return "";
  const steps = sqlAll<StepRow>(`SELECT * FROM agent_steps WHERE agent_run_id = ? ORDER BY seq`, runId);
  const color = AGENT_COLOR[r.agent] ?? "#999";
  const body = steps
    .map((s) => {
      if (s.kind === "thinking")
        return `<div class="step think"><div class="label">thinking</div>${esc(s.content)}</div>`;
      if (s.kind === "tool_call")
        return `<div class="step call"><div class="label">tool call</div><b>${esc(s.tool_name)}</b><pre>${esc(s.content)}</pre></div>`;
      if (s.kind === "tool_result") {
        const child = s.child_run_id ? renderRun(s.child_run_id, depth + 1) : "";
        return `<div class="step call ${s.is_error ? "err" : ""}"><details ${s.is_error ? "open" : ""}><summary>${s.is_error ? "tool error" : "result"} from <b>${esc(s.tool_name)}</b> (${s.content.length} chars)</summary><pre>${esc(s.content)}</pre></details>${child}</div>`;
      }
      if (s.kind === "error") return `<div class="step err"><div class="label">error</div>${esc(s.content)}</div>`;
      return `<div class="step answer"><div class="label">answer</div>${esc(s.content).replace(/\n/g, "<br>")}</div>`;
    })
    .join("");
  return `<div class="run" style="--c:${color}">
    <div class="head"><span class="tag" style="background:${color}">${esc(r.agent)}</span>
    <span>${esc(r.task)}</span><span class="muted">· ${esc(r.status)} · ${dur(r)} · AI cost ${money(r.cost_cents)}</span></div>
    ${body || '<div class="muted">starting…</div>'}</div>`;
}

ops.get("/run/:id", (c) => {
  const id = c.req.param("id");
  const [r] = sqlAll<RunRow>(`SELECT * FROM agent_runs WHERE id = ?`, id);
  if (!r) return c.html(page("Not found", "<p>No such run.</p>"), 404);
  const running = sqlAll(`SELECT 1 FROM agent_runs WHERE status='running'`).length > 0;
  return c.html(
    page(
      `${r.agent} run`,
      `<p class="muted"><a href="/ops">← all check-ins</a> · day ${r.sim_day} · ${time(r.started_at)}</p>${renderRun(id)}`,
      running
    )
  );
});

// Public home page: products as boxes on a rotating 3D turntable (three.js),
// with a plain card grid underneath for phones, slow devices and search engines.

import { esc } from "./ops.js";

interface ShelfProduct {
  slug: string;
  title: string;
  description: string;
  priceCents: number;
  type: string;
}

const TYPE_COLORS: Record<string, [string, string]> = {
  spreadsheet: ["#10b981", "#064e3b"],
  rules_pack: ["#6366f1", "#1e1b4b"],
  prompt_pack: ["#f59e0b", "#451a03"],
  code_kit: ["#06b6d4", "#083344"],
  guide: ["#ec4899", "#500724"],
  planner: ["#a855f7", "#2e1065"],
};

export function renderHome(items: ShelfProduct[], src: string): string {
  const data = items.map((p) => ({
    slug: p.slug,
    title: p.title,
    price: `$${(p.priceCents / 100).toFixed(0)}`,
    blurb: p.description.slice(0, 110),
    colors: TYPE_COLORS[p.type] ?? ["#64748b", "#0f172a"],
    type: p.type.replace("_", " "),
  }));
  const srcQs = src && src !== "direct" ? `?src=${encodeURIComponent(src)}` : "";
  const cards = items
    .map(
      (p) => `<a class="card" href="/p/${esc(p.slug)}${srcQs}">
        <span class="kind">${esc(p.type.replace("_", " "))}</span>
        <h3>${esc(p.title)}</h3><p>${esc(p.description.slice(0, 140))}</p>
        <span class="price">$${(p.priceCents / 100).toFixed(2)}</span></a>`
    )
    .join("");

  return `<!doctype html><html lang="en"><head><meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>AutoShelf — digital goods, run by AI agents</title>
<meta name="description" content="Spreadsheets, prompt packs and coding rules. Instant download.">
<style>
:root{--bg:#07080c;--text:#eef0f5;--muted:#9097a8;--line:#1d2130}
*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:15px/1.55 system-ui,-apple-system,sans-serif}
header{position:absolute;top:0;left:0;right:0;z-index:2;display:flex;align-items:center;gap:12px;padding:18px 24px}
header b{font-size:18px;letter-spacing:-.01em}header .sp{flex:1}header a{color:var(--muted);text-decoration:none;font-size:14px}
#stage{position:relative;height:min(78vh,720px);min-height:420px}
#stage canvas{display:block;width:100%;height:100%;cursor:grab}
.hero{position:absolute;left:24px;bottom:28px;z-index:2;max-width:440px;pointer-events:none}
.hero h1{margin:0 0 6px;font-size:clamp(26px,4vw,40px);letter-spacing:-.02em;line-height:1.1}
.hero p{margin:0;color:var(--muted)}
#tip{position:absolute;z-index:3;pointer-events:none;background:rgba(15,17,25,.92);border:1px solid var(--line);border-radius:10px;padding:10px 12px;max-width:260px;display:none;font-size:13px}
#tip b{display:block;font-size:14px;margin-bottom:2px}#tip .pr{color:#34d399;font-weight:700}
.grid{max-width:1040px;margin:0 auto;padding:24px 16px 72px;display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:14px}
.card{display:block;text-decoration:none;color:inherit;background:#0e1018;border:1px solid var(--line);border-radius:12px;padding:16px;transition:border-color .15s}
.card:hover{border-color:#3b4258}.card h3{margin:6px 0;font-size:16px}.card p{margin:0 0 10px;color:var(--muted);font-size:13.5px}
.kind{font-size:11px;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}.price{font-weight:700;color:#34d399}
h2{max-width:1040px;margin:8px auto 0;padding:0 16px;font-size:14px;color:var(--muted);font-weight:500;text-transform:uppercase;letter-spacing:.06em}
</style></head><body>
<header><b>AutoShelf</b><span class="sp"></span><a href="/ops">Watch the agents →</a></header>
<div id="stage"><div class="hero"><h1>Digital goods,<br>run by AI agents.</h1><p>Drag to spin the shelf. Click a box to open it.</p></div><div id="tip"></div></div>
<h2>All products</h2>
<div class="grid">${cards || "<p>No products yet.</p>"}</div>
<script type="importmap">{"imports":{"three":"https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js"}}</script>
<script type="module">
import * as THREE from "three";
const items = ${JSON.stringify(data).replace(/</g, "\\u003c")};
const srcQs = ${JSON.stringify(srcQs)};
const stage = document.getElementById("stage"), tip = document.getElementById("tip");
const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setPixelRatio(Math.min(devicePixelRatio, 2));
renderer.shadowMap.enabled = true;
stage.prepend(renderer.domElement);
const scene = new THREE.Scene();
scene.background = new THREE.Color("#07080c");
scene.fog = new THREE.Fog("#07080c", 9, 18);
const camera = new THREE.PerspectiveCamera(38, 1, 0.1, 100);
camera.position.set(0, 2.6, 8.2); camera.lookAt(0, 0.9, 0);
scene.add(new THREE.HemisphereLight("#c7d2fe", "#0b0d12", 0.9));
const key = new THREE.SpotLight("#ffffff", 60, 20, Math.PI / 5, 0.5);
key.position.set(2, 7, 4); key.castShadow = true; scene.add(key);

// turntable
const table = new THREE.Group(); scene.add(table);
const disc = new THREE.Mesh(new THREE.CylinderGeometry(3.4, 3.5, 0.18, 64),
  new THREE.MeshStandardMaterial({ color: "#151925", roughness: 0.6, metalness: 0.2 }));
disc.receiveShadow = true; table.add(disc);
const ring = new THREE.Mesh(new THREE.TorusGeometry(3.45, 0.02, 8, 96),
  new THREE.MeshBasicMaterial({ color: "#6366f1" }));
ring.rotation.x = Math.PI / 2; ring.position.y = 0.1; table.add(ring);

function face(p) {
  const c = document.createElement("canvas"); c.width = 512; c.height = 720;
  const g = c.getContext("2d");
  const grad = g.createLinearGradient(0, 0, 0, 720);
  grad.addColorStop(0, p.colors[0]); grad.addColorStop(1, p.colors[1]);
  g.fillStyle = grad; g.fillRect(0, 0, 512, 720);
  g.fillStyle = "rgba(255,255,255,.85)"; g.font = "600 30px system-ui";
  g.fillText(p.type.toUpperCase(), 40, 70);
  g.fillStyle = "#fff"; g.font = "700 52px system-ui";
  const words = p.title.split(" "); let line = "", y = 170;
  for (const w of words) {
    if (g.measureText(line + w).width > 430) { g.fillText(line, 40, y); line = ""; y += 62; if (y > 520) break; }
    line += w + " ";
  }
  if (y <= 520) g.fillText(line, 40, y);
  g.font = "800 72px system-ui"; g.fillText(p.price, 40, 660);
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 4;
  return t;
}

const boxes = [];
items.forEach((p, i) => {
  const angle = (i / items.length) * Math.PI * 2;
  const side = new THREE.MeshStandardMaterial({ color: p.colors[1], roughness: 0.5 });
  const front = new THREE.MeshStandardMaterial({ map: face(p), roughness: 0.4 });
  const box = new THREE.Mesh(new THREE.BoxGeometry(1.25, 1.75, 0.32), [side, side, side, side, front, side]);
  const r = items.length > 1 ? 2.3 : 0;
  box.position.set(Math.sin(angle) * r, 0.98, Math.cos(angle) * r);
  box.rotation.y = angle;
  box.castShadow = true; box.userData = { p, baseY: 0.98 };
  table.add(box); boxes.push(box);
});

function resize() {
  const w = stage.clientWidth, h = stage.clientHeight;
  renderer.setSize(w, h, false); camera.aspect = w / h;
  camera.position.z = w < 640 ? 10.5 : 8.2; camera.updateProjectionMatrix();
}
addEventListener("resize", resize); resize();

const ray = new THREE.Raycaster(), mouse = new THREE.Vector2();
let hovered = null, dragging = false, dragX = 0, moved = 0, spin = 0.0025;
const el = renderer.domElement;
function pick(e) {
  const b = el.getBoundingClientRect();
  mouse.set(((e.clientX - b.left) / b.width) * 2 - 1, -((e.clientY - b.top) / b.height) * 2 + 1);
  ray.setFromCamera(mouse, camera);
  return ray.intersectObjects(boxes)[0]?.object ?? null;
}
el.addEventListener("pointerdown", (e) => { dragging = true; dragX = e.clientX; moved = 0; el.style.cursor = "grabbing"; });
addEventListener("pointerup", () => { dragging = false; el.style.cursor = "grab"; });
el.addEventListener("pointermove", (e) => {
  if (dragging) { const dx = e.clientX - dragX; table.rotation.y += dx * 0.008; moved += Math.abs(dx); dragX = e.clientX; }
  hovered = pick(e);
  if (hovered) {
    const { p } = hovered.userData, b = stage.getBoundingClientRect();
    tip.innerHTML = "<b></b><span></span><div class=pr></div>";
    tip.children[0].textContent = p.title; tip.children[1].textContent = p.blurb + "…"; tip.children[2].textContent = p.price;
    tip.style.display = "block";
    tip.style.left = Math.min(e.clientX - b.left + 16, b.width - 280) + "px";
    tip.style.top = (e.clientY - b.top + 16) + "px";
    el.style.cursor = dragging ? "grabbing" : "pointer";
  } else { tip.style.display = "none"; if (!dragging) el.style.cursor = "grab"; }
});
el.addEventListener("pointerleave", () => { hovered = null; tip.style.display = "none"; });
el.addEventListener("click", (e) => {
  if (moved > 6) return;
  const hit = pick(e);
  if (hit) location.href = "/p/" + hit.userData.p.slug + srcQs;
});

const clock = new THREE.Clock();
renderer.setAnimationLoop(() => {
  const t = clock.getElapsedTime();
  if (!dragging && !hovered) table.rotation.y += spin;
  for (const b of boxes) {
    const target = b === hovered ? b.userData.baseY + 0.25 : b.userData.baseY + Math.sin(t * 1.4 + b.id) * 0.03;
    b.position.y += (target - b.position.y) * 0.12;
  }
  renderer.render(scene, camera);
});
</script></body></html>`;
}

